-- ============================================
-- 3FAPronostics — schéma Supabase
-- À coller dans Supabase > SQL Editor > Run
-- ============================================

create extension if not exists pgcrypto;

-- Équipes
create table if not exists public.teams (
  id uuid primary key default gen_random_uuid(),
  champ text not null check (champ in ('elite','d1','d2')),
  conference text check (conference in ('nord','sud') or conference is null),
  name text not null,
  logo_url text,
  created_at timestamptz default now(),
  unique (champ, name)
);

-- Matchs
create table if not exists public.matches (
  id uuid primary key default gen_random_uuid(),
  champ text not null check (champ in ('elite','d1','d2')),
  journee int,
  home_team_id uuid not null references public.teams(id) on delete cascade,
  away_team_id uuid not null references public.teams(id) on delete cascade,
  kickoff_at timestamptz not null,
  home_score int,
  away_score int,
  created_at timestamptz default now()
);

-- Profils (1 par utilisateur inscrit)
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  display_name text,
  created_at timestamptz default now()
);

-- Pronostics
create table if not exists public.predictions (
  id uuid primary key default gen_random_uuid(),
  match_id uuid not null references public.matches(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  choice text not null check (choice in ('home','draw','away')),
  created_at timestamptz default now(),
  unique (match_id, user_id)
);

-- Création automatique du profil à l'inscription
create or replace function public.handle_new_user()
returns trigger as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(new.raw_user_meta_data->>'display_name', split_part(new.email, '@', 1)));
  return new;
end;
$$ language plpgsql security definer;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute procedure public.handle_new_user();

-- Sécurité (RLS)
alter table public.teams enable row level security;
alter table public.matches enable row level security;
alter table public.predictions enable row level security;
alter table public.profiles enable row level security;

create policy "teams_select_all" on public.teams for select using (true);
create policy "teams_write_auth" on public.teams for insert to authenticated with check (true);
create policy "teams_update_auth" on public.teams for update to authenticated using (true);
create policy "teams_delete_auth" on public.teams for delete to authenticated using (true);

create policy "matches_select_all" on public.matches for select using (true);
create policy "matches_write_auth" on public.matches for insert to authenticated with check (true);
create policy "matches_update_auth" on public.matches for update to authenticated using (true);
create policy "matches_delete_auth" on public.matches for delete to authenticated using (true);

create policy "predictions_select_all" on public.predictions for select using (true);
create policy "predictions_insert_own" on public.predictions for insert to authenticated with check (auth.uid() = user_id);
create policy "predictions_update_own" on public.predictions for update to authenticated using (auth.uid() = user_id);
create policy "predictions_delete_own" on public.predictions for delete to authenticated using (auth.uid() = user_id);

create policy "profiles_select_all" on public.profiles for select using (true);
create policy "profiles_update_own" on public.profiles for update to authenticated using (auth.uid() = id);

